  const filteredCharts = charts.filter((chart) => {
    const matchesCategory =
      categoryFilter === "all" || chart.category === categoryFilter;
    const matchesStatus =
      statusFilter === "all" || chart.status === statusFilter;
    return matchesCategory && matchesStatus;
