  const publishedCount = charts.filter((c) => c.status === "active").length;
  const maxCharts = plan.limits.maxCharts;
  const isFreePlan = plan.id === "free";

  const progressPct =
    maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
  const progressColor = publishedCount >= maxCharts && maxCharts > 0 ? "#d72c0d" : "#1a73e8";

  return (
    <s-page heading="Size Charts">
      {/* Primary action */}
      <s-button
        slot="primary-action"
        variant="primary"
        onClick={() => setShowTemplates(!showTemplates)}
        disabled={!canCreate || isLoading}
      >
        {canCreate
          ? showTemplates
            ? "Cancel"
            : "Create chart"
          : `Limit reached (${plan.limits.maxCharts})`}
      </s-button>

      {/* Subtitle */}
      <s-text tone="neutral">
        Manage your size charts and assign them to products
      </s-text>

      {/* ================================================================ */}
      {/* PLAN LIMIT BANNER                                                 */}
      {/* ================================================================ */}
      {!canCreate && (
        <s-section>
          <div
            style={{
              ...cardStyle,
              background: "#fff8ec",
              border: "1px solid #ffd79d",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: "16px",
            }}
          >
            <div>
              <p
                style={{
                  margin: "0 0 4px",
                  fontSize: "14px",
                  fontWeight: 600,
                  color: "#202223",
                }}
              >
                Chart limit reached
              </p>
              <p style={{ margin: 0, fontSize: "13px", color: "#6d7175" }}>
                You have reached the {plan.limits.maxCharts}-chart limit on the {plan.name}{" "}
                plan. Upgrade to Starter for unlimited charts.
              </p>
            </div>
            <s-button href="/app/pricing" variant="primary">
              Upgrade plan
            </s-button>
          </div>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* TEMPLATE PICKER                                                   */}
      {/* ================================================================ */}
      {showTemplates && (
        <s-section>
          <div style={cardStyle}>
            {/* Header */}
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: "6px",
              }}
            >
              <div>
                <p style={sectionTitle}>Choose a starting point</p>
                <p style={{ fontSize: "13px", color: "#6d7175", margin: "4px 0 0" }}>
                  Pick a template with pre-filled sizing data, or start from scratch.
                </p>
              </div>
              <button
                onClick={() => setShowTemplates(false)}
                style={{
                  background: "none",
                  border: "1px solid #c9cccf",
                  borderRadius: "6px",
                  cursor: "pointer",
                  padding: "4px 10px",
                  fontSize: "13px",
                  color: "#6d7175",
                  lineHeight: "20px",
                }}
                aria-label="Close template picker"
              >
                Close
              </button>
            </div>

            {/* Template grid */}
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fill, minmax(180px, 1fr))",
                gap: "10px",
                marginTop: "16px",
              }}
            >
              {templates.map((template) => (
                <div
                  key={template.name}
                  style={{
                    background: "#fff",
                    border: `1px solid ${hoveredTemplate === template.name ? "#005bd3" : "#e3e3e3"}`,
                    borderRadius: "10px",
                    padding: "14px",
                    transition: "border-color 0.15s ease",
