                  onMouseEnter={() => setHoveredTemplate(template.name)}
                  onMouseLeave={() => setHoveredTemplate(null)}
                >
                  <p
                    style={{
                      margin: "0 0 4px",
                      fontWeight: 600,
                      fontSize: "14px",
                      color: "#202223",
                    }}
                  >
                    {template.name}
                  </p>
                  <p
                    style={{
                      margin: "0 0 12px",
                      fontSize: "12px",
                      color: "#6d7175",
                    }}
                  >
                    {CATEGORY_LABELS[template.category] ?? template.category} &middot;{" "}
                    {template.gender} &middot; {template.rowCount} sizes
                  </p>
                  <fetcher.Form method="post">
                    <input type="hidden" name="intent" value="create-from-template" />
                    <input type="hidden" name="templateName" value={template.name} />
                    <s-button variant="primary" type="submit" loading={isLoading}>
                      Use Template
