      {/* ================================================================ */}
      {/* FILTER BAR                                                        */}
      {/* ================================================================ */}
      <s-section>
        <div style={cardStyle}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "12px",
              flexWrap: "wrap",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
              <span style={{ fontSize: "13px", color: "#6d7175", whiteSpace: "nowrap" }}>
                Category
              </span>
              <select
                value={categoryFilter}
                onChange={(e) => setCategoryFilter((e.target as HTMLSelectElement).value)}
                style={{
                  border: "1px solid #c9cccf",
                  borderRadius: "8px",
                  padding: "6px 12px",
                  fontSize: "13px",
                  background: "#fff",
                  color: "#202223",
                  cursor: "pointer",
                  outline: "none",
                }}
              >
                <option value="all">All Categories</option>
                {categories.map((cat) => (
                  <option key={cat} value={cat}>
                    {CATEGORY_LABELS[cat] ?? cat}
                  </option>
                ))}
              </select>
            </div>

            <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
              <span style={{ fontSize: "13px", color: "#6d7175", whiteSpace: "nowrap" }}>
                Status
              </span>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter((e.target as HTMLSelectElement).value)}
                style={{
                  border: "1px solid #c9cccf",
                  borderRadius: "8px",
                  padding: "6px 12px",
                  fontSize: "13px",
                  background: "#fff",
                  color: "#202223",
                  cursor: "pointer",
                  outline: "none",
                }}
              >
                <option value="all">All Statuses</option>
                <option value="active">Active</option>
                <option value="draft">Draft</option>
              </select>
            </div>

            <span
              style={{
                marginLeft: "auto",
                fontSize: "13px",
                color: "#6d7175",
                whiteSpace: "nowrap",
              }}
            >
              {filteredCharts.length} of {charts.length} charts
            </span>
          </div>
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* CHARTS LIST                                                       */}
      {/* ================================================================ */}
      <s-section>
        <div style={cardStyle}>
