              alignItems: "center",
              marginBottom: "4px",
            }}
          >
            <p style={sectionTitle}>Size Charts ({charts.length})</p>
          </div>

          {/* Empty state — no charts at all */}
          {charts.length === 0 && (
            <div style={{ textAlign: "center", padding: "48px 24px" }}>
              <div
                style={{
                  width: "72px",
                  height: "72px",
                  borderRadius: "50%",
                  background: "#f0f5ff",
                  margin: "0 auto 16px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: "28px",
                }}
              >
                📐
              </div>
              <p
                style={{
                  fontSize: "15px",
                  fontWeight: 600,
                  color: "#202223",
                  margin: "0 0 8px",
                }}
              >
                Create your first size chart
              </p>
              <p
                style={{
                  fontSize: "13px",
                  color: "#6d7175",
                  margin: "0 0 20px",
                  maxWidth: "360px",
                  marginLeft: "auto",
                  marginRight: "auto",
                }}
              >
                Size charts help customers find their perfect fit and can reduce
                size-related returns by up to 40%. Get started in under 3 minutes
                using one of our pre-built templates.
              </p>
              <s-button variant="primary" onClick={() => setShowTemplates(true)}>
                Create your first chart
              </s-button>
            </div>
          )}

          {/* Empty state — filters applied */}
          {charts.length > 0 && filteredCharts.length === 0 && (
            <div style={{ textAlign: "center", padding: "40px 24px" }}>
              <p
                style={{
                  fontSize: "15px",
                  fontWeight: 600,
                  color: "#202223",
                  margin: "0 0 8px",
                }}
              >
                No charts match your filters
              </p>
              <p style={{ fontSize: "13px", color: "#6d7175", margin: "0 0 16px" }}>
                Try changing the category or status filters above.
              </p>
              <s-button
                onClick={() => {
                  setCategoryFilter("all");
                  setStatusFilter("all");
                }}
              >
                Clear filters
              </s-button>
            </div>
          )}

          {/* Chart rows */}
          {filteredCharts.length > 0 && (
            <div style={{ marginTop: "8px" }}>
              {filteredCharts.map((chart, i) => (
                <div
                  key={chart.id}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    padding: "14px 0",
                    borderBottom:
                      i === filteredCharts.length - 1
                        ? "none"
                        : "1px solid #f1f1f1",
                    gap: "16px",
                  }}
                >
                  {/* Left: name + meta */}
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ marginBottom: "6px" }}>
                      <s-link href={`/app/size-charts/${chart.id}`}>
                        <span
                          style={{
                            fontWeight: 600,
                            fontSize: "14px",
                            color: "#202223",
                          }}
                        >
                          {chart.name}
                        </span>
                      </s-link>
                    </div>
                    <div
                      style={{
                        display: "flex",
