                      </span>
                      <span style={{ fontSize: "12px", color: "#c9cccf" }}>&middot;</span>
                      <span style={{ fontSize: "12px", color: "#8c9196" }}>
                        Updated {formatDate(chart.updatedAt)}
                      </span>
                    </div>
                  </div>

                  {/* Right: actions */}
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "6px",
                      flexShrink: 0,
                    }}
                  >
                    <s-button href={`/app/size-charts/${chart.id}`} variant="tertiary">
                      Edit
                    </s-button>

                    <fetcher.Form method="post">
                      <input type="hidden" name="intent" value="toggle-status" />
                      <input type="hidden" name="id" value={chart.id} />
                      <s-button type="submit" loading={isLoading}>
                        {chart.status === "active" ? "Unpublish" : "Publish"}
                      </s-button>
                    </fetcher.Form>

                    <fetcher.Form method="post">
                      <input type="hidden" name="intent" value="duplicate" />
                      <input type="hidden" name="id" value={chart.id} />
                      <s-button type="submit" loading={isLoading}>
                        Duplicate
                      </s-button>
                    </fetcher.Form>

                    <fetcher.Form method="post">
                      <input type="hidden" name="intent" value="delete" />
                      <input type="hidden" name="id" value={chart.id} />
                      <s-button
                        type="submit"
                        variant="tertiary"
                        tone="critical"
                        loading={isLoading}
                      >
                        Delete
                      </s-button>
                    </fetcher.Form>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Chart Limits                                              */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Chart Limits">
        <div style={{ ...cardStyle, padding: "16px" }}>
          {/* Plan badge */}
          <div style={{ marginBottom: "12px" }}>
            <span
              style={{
                ...badgeStyle(isFreePlan ? "neutral" : "success"),
                fontSize: "12px",
              }}
            >
              {plan.name} Plan
            </span>
          </div>

          {maxCharts === -1 ? (
            <p style={{ fontSize: "13px", color: "#6d7175", margin: 0 }}>
              Unlimited charts on your plan
            </p>
          ) : (
            <>
              <p
                style={{
                  fontSize: "13px",
                  color: "#202223",
                  margin: "0 0 8px",
                  fontWeight: 600,
                }}
              >
                {publishedCount} / {maxCharts} published
              </p>
              <div
                style={{
                  height: "6px",
                  background: "#e4e5e7",
                  borderRadius: "3px",
                  overflow: "hidden",
                  marginBottom: "4px",
                }}
              >
                <div
                  style={{
                    height: "100%",
                    width: `${progressPct}%`,
                    background: progressColor,
                    borderRadius: "3px",
                    transition: "width 0.3s ease",
                  }}
                />
              </div>
              <p style={{ fontSize: "12px", color: "#8c9196", margin: "0 0 14px" }}>
                {maxCharts - publishedCount > 0
                  ? `${maxCharts - publishedCount} slot${maxCharts - publishedCount !== 1 ? "s" : ""} remaining`
                  : "Limit reached"}
              </p>

              <s-button href="/app/pricing" variant="primary">
                Upgrade for unlimited
              </s-button>
            </>
          )}
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Quick Tips                                                */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Quick Tips">
        <s-unordered-list>
          <s-list-item>
            Assign charts to products or collections for automatic display in your
            storefront widget
          </s-list-item>
          <s-list-item>
            Use templates — they include standard sizing data to get you started fast
          </s-list-item>
          <s-list-item>
            Publish a chart to make it visible to customers
          </s-list-item>
          <s-list-item>
            Add both inch and centimeter values for international customers
          </s-list-item>
        </s-unordered-list>
      </s-section>
    </s-page>
  );
}

